{
  "identity": {
    "name": "Stability Networks",
    "location": "Meridian, Idaho",
    "claims": [
      {
        "statement": "Stability Networks is located at 2289 S. Bonito Way, Ste. 150, Meridian, Idaho 83642.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "2289 S. Bonito Way, Ste. 150 Meridian, Idaho 83642"
      },
      {
        "statement": "The legal entity name is Stability Networks, Inc.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/privacy-policy/",
        "quote": "Identity of the controller: Stability Networks, Inc."
      },
      {
        "statement": "Stability Networks is a locally owned managed service provider headquartered in Meridian serving Boise, Southwest Idaho, and beyond.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/about/",
        "quote": "Elevate your business with Stability Networks, the largest locally owned MSP of tech companies in Boise, with over 20 years of excellence."
      }
    ]
  },
  "industry": {
    "industry": "Managed IT Services & Cybersecurity (MSP / MSSP)",
    "activities": [
      "Managed IT Support and Network Administration",
      "Managed Cybersecurity and Risk Assessments",
      "Data Backup and Disaster Recovery Solutions",
      "Microsoft 365 Deployment, Migration, and Modern Workplace Management",
      "Microsoft Power Platform Automation and Low-Code Development",
      "SharePoint Development and Intranet Modernization",
      "Co-Managed IT Services",
      "Unified Communications and Webex Suite by Cisco"
    ],
    "claims": [
      {
        "statement": "Stability Networks provides managed IT support, server oversight, network administration, proactive monitoring, and cybersecurity solutions.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "Complete system management including server oversight, network administration, and proactive monitoring to prevent issues before they impact your operations."
      },
      {
        "statement": "Stability Networks builds custom apps, automated workflows, and dashboards using Microsoft Power Platform.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/microsoft-power-platform/",
        "quote": "The Microsoft Power Platform gives businesses the power to rapidly solve real operational problems without waiting months for custom development or expensive software builds."
      },
      {
        "statement": "The company has over 20 years of experience, monitors over 8,000 devices, and supports over 200 customers nationwide.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/about/",
        "quote": "Supports IT for over 200+ customers nationwide Over 8,000 devices under monitoring"
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://stabilitynetworks.com/",
    "claims": [
      {
        "statement": "The company operates an online client portal on HaloPSA at stabilitypartners.halopsa.com.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "Client Portal"
      },
      {
        "statement": "Stability Networks provides IT services across multiple locations including Meridian, Nampa, Sun Valley, Caldwell, Parma, Kuna, Middleton, Mountain Home, Twin Falls, Treasure Valley, and Salt Lake City.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "Meridian Nampa Sun Valley Caldwell Parma Kuna Middleton Mountain Home Twin Falls Treasure Valley Salt Lake City"
      },
      {
        "statement": "The website was built and is powered by marketing agency Lemonade Stand.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": "Powered by Lemonade Stand"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The controller entity is identified as Stability Networks, Inc., operating in Meridian, Idaho.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/privacy-policy/",
        "quote": "Identity of the controller: Stability Networks, Inc. Address: 2289 S. Bonito Way, Ste. 150, Meridian, Idaho 83642"
      },
      {
        "statement": "Stability Networks states its engineers assist clients with federal and state regulatory frameworks including HIPAA-HITECH and PCI-DSS.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/about/",
        "quote": "Assist with Federal and State regulatory bodies, such as HIPAA-HiTECH, PCI-DSS, etc."
      },
      {
        "statement": "Stability Networks is a registered corporation in good standing in Idaho.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    ],
    "limitations": "Corporate registration records, Idaho Secretary of State filings, and professional IT licensing were not directly retrievable on the public website pages inspected."
  },
  "existingSoftware": [
    {
      "product": "HaloPSA",
      "purpose": "IT Service Management, ticketing, and client portal",
      "evidence": {
        "statement": "The client portal link and host references direct to stabilitypartners.halopsa.com.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": null
      }
    },
    {
      "product": "HubSpot",
      "purpose": "Website analytics, marketing automation, and CRM tracking",
      "evidence": {
        "statement": "HubSpot tracking scripts (hs-scripts.com/242569938.js) are loaded across the website pages.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": null
      }
    },
    {
      "product": "WordPress / Flatsome / Gravity Forms",
      "purpose": "Content management system, responsive theme, and inbound lead capture forms",
      "evidence": {
        "statement": "The site loads WordPress core files, Flatsome theme scripts, and Gravity Forms scripts with reCAPTCHA.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/contact/",
        "quote": null
      }
    },
    {
      "product": "Microsoft 365, Power Platform, SharePoint, and Copilot Studio",
      "purpose": "Internal collaboration, cloud productivity, custom workflow automation, low-code apps, and AI chatbot creation",
      "evidence": {
        "statement": "Stability Networks is Microsoft-certified and provides Power Platform, SharePoint, and Copilot Studio solutions.",
        "label": "fact",
        "sourceUrl": "https://stabilitynetworks.com/microsoft-power-platform/",
        "quote": "Microsoft-certified experts in governance, security, and solution architecture Business-first approach; we don’t build “cool apps,” we solve operational pain"
      }
    },
    {
      "product": "Trustindex",
      "purpose": "Customer review aggregation and display from Google Reviews",
      "evidence": {
        "statement": "The website loads cdn.trustindex.io to display verified Google reviews on the homepage and about page.",
        "label": "inference",
        "sourceUrl": "https://stabilitynetworks.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Stability Networks has an established contact form on its website with reCAPTCHA and HubSpot tracking, routing prospective client inquiries.",
      "label": "fact",
      "sourceUrl": "https://stabilitynetworks.com/contact/",
      "quote": "Got Questions? Give us a call or feel free to fill out our form below and we’ll be happy to assist you as soon as we can."
    },
    {
      "statement": "Stability Networks already markets and delivers the exact low-code automation, workflow automation, and custom AI agent solutions that ForgeX offers.",
      "label": "fact",
      "sourceUrl": "https://stabilitynetworks.com/microsoft-power-platform/",
      "quote": "Turn Manual Processes Into Modern Systems Without Hiring Developers This is about turning ideas into tools in days, not quarters."
    },
    {
      "statement": "Stability Networks explicitly educates clients on building custom internal AI agents and chatbots using Microsoft Copilot Studio without code.",
      "label": "fact",
      "sourceUrl": "https://stabilitynetworks.com/microsoft-365/how-copilot-studio-lets-your-business-build-custom-ai-agents-without-writing-code/",
      "quote": "Copilot Studio lets a business point an agent at its own policies, its own product catalog, its own ticketing system"
    }
  ],
  "problems": [
    {
      "problem": "Potential lead slippage or delayed follow-up on incoming web form submissions from Gravity Forms into their internal CRM/PSA.",
      "label": "hypothesis",
      "basis": "While the company uses Gravity Forms and HubSpot, it cannot be confirmed from the website whether submissions sync instantaneously to HaloPSA or generate rapid automated SMS/email follow-up."
    },
    {
      "problem": "In-house technical resources are fully capable of building automations, so purchasing external automation services is redundant.",
      "label": "inference",
      "basis": "The company's core commercial offerings include Microsoft Power Platform workflow development, SharePoint intranet automation, and Copilot Studio AI agents."
    }
  ],
  "existingSolutions": [
    {
      "solution": "HaloPSA & HubSpot Native Integrations",
      "addresses": "Lead capture, ticketing dispatch, client onboarding, and pipeline reporting.",
      "alreadyOwned": true
    },
    {
      "solution": "Microsoft Power Automate & Microsoft Power Platform",
      "addresses": "Cross-system document intake, workflow automation, approval queues, and database synchronization.",
      "alreadyOwned": true
    },
    {
      "solution": "Microsoft Copilot Studio & SharePoint Modern Workspaces",
      "addresses": "Internal knowledge retrieval, routine support triage, and policy guidance from internal company documentation.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No custom ForgeX solution is recommended. Stability Networks is an established IT MSP with specialized in-house competencies in Microsoft Power Platform, Power Automate, SharePoint, and Copilot Studio. Selling them external automation services that compete directly with their own core capabilities is commercially inappropriate."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "Stability Networks already designs and deploys AI agents internally and for clients using Microsoft Copilot Studio and the Microsoft 365 stack. External AI delivery from ForgeX provides no unique advantage."
  },
  "humanReview": [
    "Not applicable because no ForgeX implementation is recommended."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Pitching automation or AI services to an IT managed service provider whose business model includes selling low-code automation and AI agent design risks damaging ForgeX's credibility."
    },
    {
      "type": "compliance",
      "description": "Stability Networks manages systems under strict regulatory controls (HIPAA, PCI-DSS); introducing third-party automation tools outside their governed Microsoft/HaloPSA architecture would trigger compliance friction."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "Stability Networks has the in-house engineering expertise to automate its own workflows without third-party vendor fees.",
      "There is no verifiable evidence that Stability Networks has a budget or desire for outsourced SMB workflow automation."
    ]
  },
