  "discovery": {
    "questions": [
      "How does your team currently bridge inbound website leads from Gravity Forms and HubSpot into HaloPSA for immediate SLA tracking?",
      "As a provider of Microsoft Power Platform and Copilot Studio solutions, do you manage all your internal business automations in-house, or do you ever partner with specialist subcontractors during high-capacity periods?"
    ],
    "outreachSubject": "Partnership inquiry / Capacity support for Microsoft Power Platform builds",
    "outreachBody": "Hi [First Name],\n\nI was reviewing Stability Networks' work in the Treasure Valley and noted your dedicated offerings around Microsoft Power Platform and Copilot Studio agent builds.\n\nAt ForgeX, we develop fixed-scope workflow automations and pipeline connectors. Rather than pitching internal tools that your engineers can easily build yourselves, we wanted to see if your team ever uses specialized subcontracting support when client demand for Power Platform or custom integration work exceeds your internal bench capacity.\n\nIf exploring a white-label or overflow development partnership makes sense, I would be glad to share our delivery model.\n\nBest regards,\n\n[Founder Name]\nForgeX\n[Postal Address]\nOpt-out: Reply with 'unsubscribe' to be immediately removed from all future correspondence."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://stabilitynetworks.com/",
        "usedFor": "Company identity, core services, location, phone number, customer reviews, script stack inspection."
      },
      {
        "url": "https://stabilitynetworks.com/about/",
        "usedFor": "Company background, operational scale (200+ clients, 8,000+ devices, 20+ years), engineering credentials."
      },
      {
        "url": "https://stabilitynetworks.com/contact/",
        "usedFor": "Contact channels, phone support lines, client support protocols, web form structure."
      },
      {
        "url": "https://stabilitynetworks.com/microsoft-power-platform/",
        "usedFor": "Evaluation of existing software capabilities and existing commercial offerings in low-code automation."
      },
      {
        "url": "https://stabilitynetworks.com/sharepoint-development/",
        "usedFor": "Evaluation of existing SharePoint document management, workflow automation, and intranet services."
      },
      {
        "url": "https://stabilitynetworks.com/masters-service-agreement/",
        "usedFor": "Contract structure, service exclusions, terms of service review."
      },
      {
        "url": "https://stabilitynetworks.com/privacy-policy/",
        "usedFor": "Legal entity name (Stability Networks, Inc.), corporate address, administrative phone number, compliance coverage."
      },
      {
        "url": "https://stabilitynetworks.com/blog/",
        "usedFor": "Content analysis regarding AI governance, Copilot Studio, and MSP technology capabilities."
      },
      {
        "url": "https://stabilitynetworks.com/microsoft-365/how-copilot-studio-lets-your-business-build-custom-ai-agents-without-writing-code/",
        "usedFor": "Evidence of in-house expertise in building custom AI agents and chatbots using Microsoft Copilot Studio."
      },
      {
        "url": "https://stabilitynetworks.com/locations/",
        "usedFor": "Regional coverage validation and recruitment email address identification."
      }
    ],
    "limitations": [
      "Executive and owner names are not published on the website; only engineering team members are identified via client testimonials.",
      "General administrative or direct executive email addresses are masked by Cloudflare email protection or redirected via contact forms, with only [redacted] exposed as a direct mailto URI.",
      "Internal ticketing response metrics and actual conversion rates from web forms into HaloPSA cannot be verified from external observation."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Per the founder's explicit guidelines: 'Existing software capabilities should always be evaluated before recommending custom development' and 'The better answer may be that the company does not need ForgeX or already owns the necessary solution.' Stability Networks is a mature Managed IT and Cybersecurity provider with over 20 years of experience, 200+ customers, and an in-house engineering team that already specializes in Microsoft Power Platform, SharePoint automation, and Microsoft Copilot Studio AI agents. They already sell and deploy the same automation and AI agent services that ForgeX offers. Selling end-user automation packages to them is not viable; at most, only a potential subcontractor/overflow relationship could exist."
  }
